+import { createHmac, randomBytes } from "crypto";
 import { pool } from "./pool.ts";

 export interface Session {
@@ -6,6 +7,16 @@ export interface Session {
   revokedAt: Date | null;
 }

+interface SignedPayload {
+  sessionId: string;
+  userId: string;
+  iat: number;
+  exp: number;
+}
+
+const SIGNING_KEY = process.env.SESSION_SIGNING_KEY || randomBytes(32).toString("hex");
+const TOKEN_EXPIRY = 24 * 60 * 60; // 24 hours in seconds
+
 export const loadSession = async (id: string): Promise<Session | null> => {
   const result = await pool.query(
     "SELECT id, user_id, revoked_at FROM sessions WHERE id = $1",
@@ -19,3 +30,52 @@ export const loadSession = async (id: string): Promise<Session | null> => {
 export const revokeSession = async (id: string): Promise<void> => {
   await pool.query("UPDATE sessions SET revoked_at = now() WHERE id = $1", [id]);
 };
+
+export const createSessionToken = (sessionId: string, userId: string): string => {
+  const now = Math.floor(Date.now() / 1000);
+  const payload: SignedPayload = {
+    sessionId,
+    userId,
+    iat: now,
+    exp: now + TOKEN_EXPIRY,
+  };
+
+  const header = Buffer.from(JSON.stringify({ alg: "HS256", typ: "JWT" })).toString(
+    "base64url",
+  );
+  const body = Buffer.from(JSON.stringify(payload)).toString("base64url");
+  const message = `${header}.${body}`;
+
+  const signature = createHmac("sha256", SIGNING_KEY).update(message).digest("base64url");
+
+  return `${message}.${signature}`;
+};
+
+export const verifySessionToken = (token: string): Session | null => {
+  try {
+    const [headerB64, bodyB64, signatureB64] = token.split(".");
+    if (!headerB64 || !bodyB64 || !signatureB64) return null;
+
+    const message = `${headerB64}.${bodyB64}`;
+    const expectedSignature = createHmac("sha256", SIGNING_KEY)
+      .update(message)
+      .digest("base64url");
+
+    if (signatureB64 !== expectedSignature) return null;
+
+    const payload = JSON.parse(Buffer.from(bodyB64, "base64url").toString()) as SignedPayload;
+    const now = Math.floor(Date.now() / 1000);
+
+    if (payload.exp < now) return null;
+
+    return {
+      id: payload.sessionId,
+      userId: payload.userId,
+      revokedAt: null,
+    };
+  } catch {
+    return null;
+  }
+};
+
+export const getSigningKey = (): string => SIGNING_KEY;
